/* Isolated design prototype. All scans, content, traffic and launches are simulated. */
'use strict';
const $ = selector => document.querySelector(selector);
const esc = value => String(value).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons = {
  arrow:'M4 10h12m-5-5 5 5-5 5', check:'m4 10 4 4 8-8', globe:'M10 2a8 8 0 1 0 0 16 8 8 0 0 0 0-16M2 10h16M10 2c-5 5-5 11 0 16 5-5 5-11 0-16',
  block:'m10 2 8 4-8 4-8-4 8-4m-8 4v8l8 4 8-4V6M10 10v8', chart:'M3 3v14h14M6 12l4-4 3 2 4-6', lock:'M6 9V6a4 4 0 0 1 8 0v3M4 9h12v9H4z',
  sparkle:'m10 2 2 6 6 2-6 2-2 6-2-6-6-2 6-2z', clock:'M10 2a8 8 0 1 0 0 16 8 8 0 0 0 0-16M10 5v5l3 2', refresh:'M16 7a7 7 0 1 0 1 6M16 2v5h-5',
  edit:'m3 14 11-11 3 3L6 17H3v-3m9-9 3 3', mail:'M2 4h16v12H2zM2 4l8 7 8-7', shield:'m10 2 7 3v5c0 4-7 8-7 8s-7-4-7-8V5zM6 10l3 3 5-5',
  back:'M16 10H4m5-5-5 5 5 5', pause:'M7 4v12M13 4v12', play:'m6 3 11 7-11 7z', eye:'M1 10s4-6 9-6 9 6 9 6-4 6-9 6-9-6-9-6M10 7a3 3 0 1 0 0 6 3 3 0 0 0 0-6'
};
const icon = name => `<svg viewBox="0 0 20 20" aria-hidden="true"><path d="${icons[name] || icons.arrow}"/></svg>`;
const steps = [
  ['connect','Connect'],['scan','Discover'],['understand','Refine brief'],['recommend','Change page'],['preview','Preview'],['launch','Launch'],['live','First visitors'],['followup','Come back']
];
const initial = {step:'connect',resume:'connect',entry:'plugin',url:'northstar.example',goal:'Leads',brief:'You help growing teams move to WordPress. Your website turns interested visitors into migration enquiries.',page:'home',idea:'headline',variant:'Move to WordPress.\nKeep your momentum.',personalizedVariant:'Your next campaign.\nOn a better foundation.',discovery:'',scan:0,scenario:'normal',mode:'test',audience:'Campaign visitors',device:'desktop',edit:false,approved:false,launched:false,paused:false,exposed:false,day:2,notes:false,readiness:'ready',connectedUrl:'northstar.example',assistance:'assisted',prepared:false,reviewed:false,connected:true,aiTool:'',aiPrompt:'',otherSource:'',notifications:false,collection:'unknown',connectionState:'ready',setupHidden:false,sourcePage:'',sourceHeading:'',active:null,events:[]};
let state = {...initial};
try { const saved = JSON.parse(localStorage.getItem('accelerate-onboarding-prototype-v1')); if (saved && typeof saved === 'object') { for (const key of Object.keys(initial)) if (key!=='active'&&key!=='events'&&typeof saved[key] === typeof initial[key]) state[key] = saved[key]; if(Array.isArray(saved.events))state.events=saved.events.filter(e=>e&&typeof e.name==='string'&&typeof e.at==='string').slice(-60); if(saved.active&&pagesSafe(saved.active.page))state.active=saved.active; } } catch (_) { /* File URLs or private sessions may not allow persistence. */ }
function pagesSafe(page){return ['home','services','contact'].includes(page);}
let scanTimer, toastTimer;
const sessionStart=Date.now();
const pages = {
  home:{name:'Homepage',path:'/',reason:'Your front page',detail:'The first place many visitors will learn what you do.',section:'Hero section',original:'A better home\nfor your website.',headline:'Move to WordPress.\nKeep your momentum.'},
  services:{name:'Migration services',path:'/services/',reason:'Featured in your navigation',detail:'A high-intent page where visitors compare your offer.',section:'Service introduction',original:'WordPress migration,\nmade simple.',headline:'A smooth move.\nA stronger website.'},
  contact:{name:'Get in touch',path:'/contact/',reason:'Contains your enquiry form',detail:'A natural place to reduce hesitation before an enquiry.',section:'Enquiry introduction',original:'Let’s talk about\nyour next move.',headline:'Your next chapter\nstarts with a conversation.'}
};
const goals = {Leads:['Start more conversations','Link clicks in this section'],Clarity:['Explain the migration journey','Link clicks in this section'],Confidence:['Show the support around the move','Link clicks in this section']};
function currentPage(){const page=pages[state.page]||pages.home;return state.sourcePage===state.page&&state.sourceHeading?{...page,original:state.sourceHeading}:page;}
function save(){try{localStorage.setItem('accelerate-onboarding-prototype-v1',JSON.stringify(state));}catch(_){}}
function toast(message){clearTimeout(toastTimer);$('#toast').textContent=message;$('#toast').classList.add('visible');toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3500);}
function go(step){clearInterval(scanTimer);state.step=step;state.edit=false;record('step_viewed',step);if(step==='preview'&&!state.prepared){state.prepared=true;record('first_value_reached','draft');}if(step!=='dashboard')state.resume=step;save();history.replaceState(null,'','#'+step);render();$('#screen').focus({preventScroll:true});window.scrollTo({top:0,behavior:'instant'});if(step==='scan'&&state.scan<4&&state.scenario!=='scan-error')startScan();}
const button=(text,action,style='primary',extra='')=>`<button class="btn ${style}" data-action="${action}" ${extra}>${text}</button>`;
const back=(step)=>button(icon('back')+'Back','go:'+step,'');
function footer(left,right){return `<footer class="footer"><div class="footer-left">${left}</div>${right}</footer>`;}
function record(name,detail=''){state.events.push({name,detail,elapsedMs:Date.now()-sessionStart,at:new Date().toLocaleTimeString([], {hour:'2-digit',minute:'2-digit',second:'2-digit'})});state.events=state.events.slice(-60);}
function changed(){state.approved=false;state.reviewed=false;}
function headline(){return state.mode==='personalization'?state.personalizedVariant:state.variant;}
function proposalCTA(){return state.goal==='Clarity'?'Explore the migration plan':state.goal==='Confidence'?'Meet your migration team':'Plan my migration';}
function changeTable(){return `<table class="result-table change-table"><caption>What you are approving</caption><thead><tr><th>In this section</th><th>Original</th><th>Proposed</th></tr></thead><tbody><tr><th>Headline</th><td>${esc(currentPage().original)}</td><td>${esc(headline())}</td></tr><tr><th>Invitation</th><td>Let’s talk</td><td>${esc(state.assistance==='manual'?'Let’s talk':proposalCTA())}</td></tr><tr><th>Supporting content</th><td>Service introduction</td><td>${state.assistance==='manual'?'Original copy retained':'A three-part migration journey, drawn from existing services'}</td></tr></tbody></table>`;}
function sitePreview({proposed=false,highlight=false,compact=false}={}){
 const p=currentPage(); const manual=state.assistance==='manual';
 return `<div class="browser-card"><div class="browser-top">${icon('lock')}${esc(state.url)}${p.path==='/'?'':p.path}<span class="fixture-tag">Example site</span></div><div class="demo-site"><div class="demo-nav"><span class="demo-name">northstar.</span><div class="demo-links"><span>Our work</span><span>Services</span><span>About</span></div></div><div class="demo-hero ${highlight?'selected-block':''}">${highlight?'<span class="block-tag">'+esc(p.section)+'</span>':''}<h2>${esc(proposed?headline():p.original).replace(/\n/g,'<br>')}</h2><p>${proposed&&!manual?'A considered migration, a familiar team, and a website ready for what comes next.':'We design, build and care for WordPress websites. Let’s make something that moves you forward.'}</p><span class="demo-cta">${proposed&&!manual?proposalCTA():'Let’s talk'}${icon('arrow')}</span>${proposed&&!manual?'<div class="demo-quote">Understand your site. Plan the move. Keep growing.<small>Strategy · Migration · Ongoing care</small></div>':''}</div>${compact?'':`<div class="site-bottom"><div><b>Strategy</b>A clear way forward</div><div><b>Migration</b>A considered move</div><div><b>Care</b>Here for the long run</div></div>`}</div></div>`;
}
function connect(){return `<div class="screen-body split main-in"><div class="intro"><div class="entry-toggle" aria-label="Entry point"><button data-action="entry:plugin" class="${state.entry==='plugin'?'selected':''}" aria-pressed="${state.entry==='plugin'}">Inside WordPress</button><button data-action="entry:website" class="${state.entry==='website'?'selected':''}" aria-pressed="${state.entry==='website'}">From the website</button></div><h1>Your first improvement,<br>already taking shape.</h1><p class="description">Let Accelerate read your website and prepare a complete first idea. See it in your design, adjust it, and decide whether to launch.</p><form id="connect-form"><label class="field-label" for="site-url">Website to explore</label><input class="input" id="site-url" value="${esc(state.url)}" autocomplete="url" required aria-describedby="url-help url-error"><p class="field-help" id="url-help">${state.entry==='plugin'?'Connected installation: '+esc(state.connectedUrl)+'. A different site needs its own connection before launch.':'Start with public content. You can see and save your draft before connecting WordPress.'}</p><p id="url-error" class="error" role="alert"></p><div class="permission-note"><h3>What you’re allowing</h3><p>Use public page content to prepare an assisted suggestion. No private posts, visitor records or site changes are needed for this first draft.</p><p class="fine">This prototype uses Northstar sample content for every address. No analysis is sent.</p></div><button class="btn primary" type="submit">Prepare my first idea${icon('arrow')}</button></form><button class="text-button manual-link" data-action="manual">I’ll start from my current content</button></div><div class="preview-stack">${sitePreview({proposed:true})}<div class="insight-note">${icon('sparkle')}<div><strong>A preview of what you’ll get</strong><p>A proposed headline, invitation and migration journey. Your first result is a draft; publishing is a separate decision.</p></div></div></div></div>${footer('<span class="fine">You can leave at any point. Your draft stays here.</span>',button('Explore setup later','skip',''))}`;}

function scan(){
 const failed=state.scenario==='scan-error';const completed=state.scan===4;
 const tasks=['Public pages located','Editable content matched','Offer and tone inferred','First treatment prepared'];
 return `<div class="screen-body split main-in"><div><h1>${failed?'We couldn’t read this site.':completed?'Your first idea is ready.':'Preparing something you can use.'}</h1><p style="margin-top:16px">${failed?'Your address is saved. You can retry or work with the content already available.':completed?'We’ve prepared a migration invitation on your homepage. You can change the page or direction after you see it.':'We’re using your offer and existing services to shape a first draft. You can use available content without waiting.'}</p>${failed?`<div class="error-state"><h3>Analysis unavailable</h3><p>No draft was generated by this failed request. Your current content is still available.</p><div class="button-row">${button('Retry analysis','retry')}${button('Use current content','manual','')}</div></div>`:`<ul class="scan-list" aria-live="polite">${tasks.map((task,i)=>`<li class="${i<state.scan?'complete':'pending'}">${icon(i<state.scan?'check':'clock')}<div>${task}<small>${i<state.scan?'Example result available':'Not complete in this simulation'}</small></div></li>`).join('')}</ul><p class="fine">Simulated progress. Production progress must come from completed work, not a timer.</p>`}${state.entry==='plugin'?attribution():''}</div><div class="preview-stack">${sitePreview({proposed:completed})}<div class="insight-note">${icon('eye')}<div><strong>${completed?'Homepage · migration invitation':'Your content is already a starting point'}</strong><p>Suggested because it introduces your offer. We haven’t measured which page gets the most visits.</p></div></div></div></div>${footer(back('connect')+`<label class="scenario">Reviewer scenario<select id="scan-scenario"><option value="normal" ${!failed?'selected':''}>Prepared successfully</option><option value="scan-error" ${failed?'selected':''}>Analysis unavailable</option></select></label>`,completed?button('See my prepared idea'+icon('arrow'),'go:preview'):button('Use available content now','local-content',''))}`;
}
function attribution(){return `<details class="attribution" ${state.discovery?'open':''}><summary>Optional: how did you hear about Accelerate?</summary><div class="chips">${['AI assistant','Web search','Video','Newsletter or blog','Friend or colleague','Social media','Event or community','Other'].map(source=>`<button class="chip ${state.discovery===source?'selected':''}" aria-pressed="${state.discovery===source}" data-action="discovery:${source}">${source}</button>`).join('')}</div>${state.discovery?'<p class="fine" role="status">Thanks, that helps. You can continue without answering anything else.</p>':''}${state.discovery==='AI assistant'?`<label class="field-label" for="ai-tool">Which assistant? (optional)</label><select id="ai-tool"><option value="">Choose an assistant</option>${['ChatGPT','Claude','Perplexity','Gemini','Other'].map(tool=>`<option ${state.aiTool===tool?'selected':''}>${tool}</option>`).join('')}</select><label class="field-label" for="ai-prompt">Roughly what did you ask? (optional)</label><textarea id="ai-prompt" maxlength="400" rows="2" placeholder="For example, how can I improve my WordPress site?">${esc(state.aiPrompt)}</textarea><p class="fine">Leave out private details. Stored only in this demo browser, never in the event receipt.</p>`:state.discovery==='Other'?`<label class="field-label" for="other-source">Where? (optional)</label><input class="input" id="other-source" maxlength="120" value="${esc(state.otherSource)}">`:''}</details>`;}

function understand(){return `<div class="screen-body main-in"><div class="page-title"><div><h1>Does this sound like you?</h1><p>A little understanding goes a long way. Correct anything we’ve missed.</p></div><span class="status purple">${state.scenario==='local'?'From WordPress content':'From your website'}</span></div><div class="understanding"><div class="brief-box"><div class="status neutral">Our read of ${esc(state.url)}</div>${state.edit?`<label class="field-label" for="brief-edit">What your business does</label><textarea id="brief-edit" rows="5">${esc(state.brief)}</textarea><div class="button-row" style="margin-top:10px">${button('Save changes','save-brief','primary small')}${button('Cancel','cancel-edit','small')}</div>`:`<p class="brief-sentence">${esc(state.brief)}</p><button class="text-button" data-action="edit-brief">Edit this description</button>`}<div class="facts"><div class="fact"><span>Voice</span><strong>Clear, considered, reassuring</strong></div><div class="fact"><span>Likely audience</span><strong>Growing business teams</strong></div><div class="fact"><span>Starting content</span><strong>3 pages to explore</strong></div></div></div><div><h3>What should this draft emphasise?</h3><p class="fine" style="margin-top:6px">Recommended: start more conversations. Changing this updates the headline and invitation; measurement stays in-section link clicks.</p><div class="goal-list" aria-label="Your main goal">${Object.entries(goals).map(([g,v])=>`<button class="choice ${state.goal===g?'selected':''}" data-action="goal:${g}" aria-pressed="${state.goal===g}"><span class="radio"></span><span><strong>${g==='Leads'?'Conversations · recommended':g==='Clarity'?'A clearer journey':'A familiar team'}</strong><small>${v[0]}</small></span>${state.goal===g?icon('check'):''}</button>`).join('')}</div></div></div></div>${footer(back('preview'),button('Apply to my draft'+icon('arrow'),'go:preview'))}`;}
function ideaTitle(){if(state.mode==='personalization')return 'Welcome campaign visitors in context.';return state.idea==='cta'?'Make the next step more specific.':state.idea==='proof'?'Bring the team closer to the decision.':'Lead with the outcome, not the service.';}
function recommend(){const p=currentPage();return `<div class="screen-body main-in"><div class="page-title"><div><h1>Start with a moment that matters.</h1><p>These look like important pages. Choose one and we’ll prepare a focused improvement.</p></div></div><div class="recommend-layout"><div><div class="page-choices">${Object.entries(pages).map(([id,p])=>`<button class="page-choice ${state.page===id?'selected':''}" data-action="page:${id}" aria-pressed="${state.page===id}"><strong>${p.name}</strong><span class="path">${p.path}</span><small>${p.reason}</small></button>`).join('')}</div><p class="fine" style="margin-top:15px">Suggested from your site structure. Real traffic will refine these choices.</p></div><div><div class="recommend-main"><div class="recommend-header"><span class="status purple">Suggested for ${esc(state.goal.toLowerCase())}</span><h3>${ideaTitle()}</h3></div><div class="recommend-detail"><div><h3>${p.name} · ${p.section.toLowerCase()}</h3><p>${state.idea==='headline'?'Rebuild the invitation around the outcome: a clearer promise, a focused call to action and a three-part view of the migration journey.':state.idea==='cta'?'“Let’s talk” leaves the next step open. Give visitors a clearer reason to click with a specific, low-pressure invitation.':'Show the strategy, migration and ongoing care that already exist in your offer. Do not invent testimonials or guarantees.'}</p><div class="rationale"><strong>Why here?</strong><br>${p.detail} ${'We can measure link clicks in this section. Completed enquiries or purchases need a separate verified integration.'}</div></div>${sitePreview({highlight:true,compact:true})}</div></div><div class="alternative"><span class="fine">Or try:</span>${[['headline','A complete migration invitation'],['cta','A more specific button'],['proof','The team around the move']].filter(([id])=>id!==state.idea).map(([id,label])=>`<button class="text-button" data-action="idea:${id}">${label}</button>`).join('')}</div></div></div></div>${footer(back('understand'),button('Prepare this idea'+icon('arrow'),'go:preview'))}`;}
function websiteConnect(){const pending=state.connectionState==='pending';const failed=state.connectionState==='failed';return `<div class="screen-body split main-in"><div class="intro"><h1>${pending?'Your draft is ready for an administrator.':failed?'The connection didn’t finish.':'Keep your idea. Connect when you’re ready.'}</h1><p class="description">${pending?'You can keep editing. An administrator on the target WordPress site needs to authorise publishing.':failed?'Nothing was published. Retry the connection or return to your saved draft.':'Your first result is already here. A connection lets Accelerate match it to an editable section and prepare a safe launch.'}</p><div class="permission-note"><h3>Connection scope</h3><p>Read this site’s published content, theme and available experiment controls. Publishing one reviewed placement requires a separate approval.</p><p class="fine">No credentials are created or collected in this prototype.</p></div>${pending?button('Simulate administrator approval','finish-wordpress'):button(failed?'Retry connection':'Connect this WordPress site','finish-wordpress')}<div class="button-row" style="margin-top:15px">${button('Keep editing my draft','go:preview','')}${button('Do this later','skip','')}</div><label class="scenario">Reviewer · connection<select id="connection-scenario"><option value="ready" ${state.connectionState==='ready'?'selected':''}>Administrator available</option><option value="pending" ${pending?'selected':''}>Approval pending</option><option value="failed" ${failed?'selected':''}>Connection failed</option></select></label></div><div><div class="status purple">Your prepared draft is saved</div>${sitePreview({proposed:true})}</div></div>${footer(back('preview'),'<span class="fine">Connect only the installation that owns this page.</span>')}`;}

function preview(){return `<div class="screen-body draft-screen main-in"><div class="page-title"><div><h1>Your first idea, in your own design.</h1><p>${state.assistance==='manual'?'Start with the original and edit the headline. You can ask for an assisted treatment whenever you want.':'We’ve prepared the headline, invitation and supporting journey together. Make the draft yours before thinking about launch.'}</p></div><span class="status purple">${state.assistance==='manual'?'Manual draft':'Recommended starting point'}</span></div><div class="draft-context"><div><strong>${currentPage().name} · ${currentPage().section}</strong><p>Based on your migration, strategy and care content. The opportunity is an inference, not a performance finding.</p></div><div class="button-row">${button('Change the direction','go:understand','small')}${button('Choose another page','go:recommend','small')}</div></div><div class="preview-toolbar"><span class="fine">Try this: compare the invitation, then check the narrow view.</span><div class="button-row"><div class="segmented" aria-label="Preview size"><button data-action="device:desktop" class="${state.device==='desktop'?'selected':''}" aria-pressed="${state.device==='desktop'}">Desktop</button><button data-action="device:mobile" class="${state.device==='mobile'?'selected':''}" aria-pressed="${state.device==='mobile'}">Mobile</button></div><button class="text-button" data-action="edit-variant">Edit headline</button></div></div><div class="preview-columns ${state.device==='mobile'?'mobile':''}"><div><div class="preview-label">Original<small>Saved source content</small></div>${sitePreview()}</div><div><div class="preview-label">${state.mode==='personalization'?'Campaign welcome':'Your prepared draft'}<small>Not published</small></div>${sitePreview({proposed:true})}</div></div>${state.edit?`<form id="headline-form" class="edit-panel"><label class="field-label" for="variant-edit">Proposed headline</label><textarea id="variant-edit" maxlength="150" required>${esc(headline())}</textarea><div class="button-row"><button class="btn primary small" type="submit">Update preview</button>${button('Cancel','cancel-edit','small')}</div></form>`:''}<details class="proposal-detail"><summary>Working site brief</summary><p>${esc(state.brief)}</p><p class="fine">This editable interpretation travels with your draft. It is not a verified business fact.</p></details><details class="proposal-detail"><summary>Review the exact changes</summary>${changeTable()}<p class="fine">No customer quotes or success statistics were generated. Check that this wording matches your actual offer.</p></details><div class="change-summary">${icon('shield')}<span>First draft prepared. Your website is unchanged. Launch setup is the next, separate step.</span></div>${state.assistance==='manual'?button('Prepare an assisted treatment','assist','small'):button('Use my original as the starting point','manual','small')}</div>${footer(button('Keep this draft for later','skip',''),button('Keep this idea. Review setup'+icon('arrow'),'review-setup'))}`;}

function launchBlocked(){return !['ready','publish-failure'].includes(state.readiness)||!state.connected||state.connectedUrl!==state.url||!!state.active||(state.assistance==='manual'&&headline()===currentPage().original);}
function readinessPanel(){
 const r=state.readiness;
 if(state.assistance==='manual'&&headline()===currentPage().original)return `<div class="error-state"><h3>Your draft still matches the original.</h3><p>Edit the headline or choose an assisted treatment before creating an experience.</p>${button('Edit my draft','go:preview','small')}</div>`;
 if(state.active)return `<div class="error-state"><h3>Your first experience is still running.</h3><p>This new idea is a separate draft. Review the live experience before replacing it.</p>${button('View live experience','go:live','small')}</div>`;
 if(!state.connected||state.connectedUrl!==state.url||r==='staging')return `<div class="error-state"><h3>Connect the installation that owns this page.</h3><p>A public URL gives us context, not permission to edit. Your draft stays saved.</p>${button('Review connection','connect-wordpress','small')}</div>`;
 const issues={shared:['This pattern is used on four pages.','Prepare a separate pattern so the other three placements keep their original content.','Isolate this placement'],unmapped:['This section cannot be mapped safely.','Keep your idea and use the verified homepage section instead.','Choose the mapped homepage section'],stale:['The page changed after this draft was prepared.','Compare your draft with the latest source before approving again. We won’t overwrite the newer edit.','Refresh source and review'],permission:['An administrator needs to approve access.','Your current role can prepare the idea, but cannot authorise this site change.','Review administrator approval'],failed:['Publish could not be verified.','The example transaction was rolled back to the original. Your draft is kept; approval is cleared.','Review draft before retrying']};
 if(issues[r]){const [title,body,label]=issues[r];return `<div class="error-state" role="status"><h3>${title}</h3><p>${body}</p>${button(label,'resolve-readiness','small')}</div>`;}
 return `<div class="readiness-ok">${icon('check')}One placement matched · source checked · original recovery prepared</div>`;
}

function launch(){const personal=state.mode==='personalization';const blocked=launchBlocked();return `<div class="screen-body main-in"><div class="page-title"><div><h1>Turn your draft into a live experience.</h1><p>Review what changes, who sees it and what we can learn.</p></div><span class="status neutral">${blocked?'Setup needs attention':'Awaiting your approval'}</span></div><div class="launch-layout"><div><div class="segmented" aria-label="Experience type"><button data-action="mode:test" class="${!personal?'selected':''}" aria-pressed="${!personal}">A/B test · recommended</button><button data-action="mode:personalization" class="${personal?'selected':''}" aria-pressed="${personal}">Campaign welcome</button></div><p class="fine" style="margin-top:10px">${personal?'A relevant welcome now, without claiming it performs better.':'Compare the complete treatment with the original. Low traffic may mean a long wait for a useful result.'}</p><div class="summary-rows"><div class="summary-row"><span>Placement</span><strong>${currentPage().name} · ${currentPage().section}<br><span class="fine">One placement. Other pages stay unchanged.</span></strong></div><div class="summary-row"><span>Audience</span><strong>${personal?'Recorded campaign equals “migration”':'Eligible visitors allocated between both versions'}<br><span class="fine">${personal?'Includes remembered campaign visits. Everyone else keeps the original.':'Allocation starts equally and may adapt. Preview visits do not count.'}</span></strong></div><div class="summary-row"><span>Measure</span><strong>Link clicks inside this section<br><span class="fine">An intent signal, not verified enquiries or purchases elsewhere.</span></strong></div></div><details class="proposal-detail" open><summary>Exact content changes</summary>${changeTable()}</details>${readinessPanel()}<label class="consent"><input id="launch-consent" type="checkbox" ${state.approved?'checked':''} ${blocked?'disabled':''}>I reviewed this placement, audience and content, and approve showing it on ${esc(state.url)}.</label></div><aside class="launch-aside"><h3>What happens after approval?</h3><ol class="launch-sequence"><li>Keep the original and check the source revision.</li><li>Publish only this approved placement.</li><li>Verify the rendered experience.</li><li>Wait for a valid visitor exposure.</li></ol><p>Publishing and reaching a visitor are separate milestones. If verification fails, keep the draft and restore the original.</p><details class="proposal-detail"><summary>Connection and plan requirements</summary><p>The connected account must allow this feature, and your WordPress role must allow this placement to be changed. No pricing or plan entitlement is assumed by this demo.</p></details></aside></div></div>${footer(back('preview')+`<label class="scenario">Reviewer scenario<select id="readiness-scenario">${[['ready','Ready'],['shared','Shared pattern'],['staging','Staging connection'],['unmapped','Unmapped section'],['permission','Administrator approval'],['stale','Page changed'],['publish-failure','Publish verification fails']].map(([v,l])=>`<option value="${v}" ${state.readiness===v?'selected':''}>${l}</option>`).join('')}</select></label>`,button('Publish this experience'+icon('arrow'),'launch','primary',state.approved&&!blocked?'':'disabled'))}`;}

function live(){const a=state.active;if(!a)return `<div class="screen-body"><h1>Your draft is still a draft.</h1><p>Review and approve it before there is a live experience to report.</p>${button('Return to my draft','go:preview')}</div>`;return `<div class="screen-body main-in"><div class="live-layout"><div><div class="success-symbol">${icon(a.paused?'pause':a.exposed?'eye':'check')}</div><h1>${a.paused?'Paused. Your original is showing.':a.exposed?'Your idea has reached a visitor.':'Published and checked. A good first step.'}</h1><p style="margin-top:17px">${a.exposed?'You’ve crossed from a draft to a delivered experience. That is activation; whether the idea works better still needs evidence.':'Your change is live in this example. The next milestone is an eligible visitor actually seeing the section.'}</p><div class="timeline"><div class="timeline-item">${icon('check')}<div><strong>One placement changed</strong><p>${pages[a.page].name} · ${pages[a.page].section}. Other pages are unchanged.</p></div></div><div class="timeline-item">${icon('check')}<div><strong>Rendered experience verified</strong><p>Original retained. ${a.mode==='test'?'Pause or restore from this screen.':'Restore to remove the targeting.'}</p></div></div><div class="timeline-item">${icon(a.exposed?'check':'clock')}<div><strong>${a.exposed?'43 eligible block views · 2 link clicks':'Still missing: a valid visitor exposure'}</strong><p>Example events, not unique people. Admin previews do not count.</p></div></div></div><div class="button-row">${!a.exposed&&!a.paused?`<label class="scenario">Reviewer scenario<span>${button('Simulate eligible exposure','exposure','')}</span></label>`:''}${button('Check visitor collection','tracking-check','')}</div>${collectionPanel()}</div><aside><div class="live-summary"><span class="status">${a.paused?'Paused':a.mode==='test'?'A/B test running':'Campaign welcome running'}</span><h3 style="margin-top:12px">${esc(a.variant)}</h3><p style="margin:15px 0">Measure: in-section link clicks</p><div class="button-row">${a.mode==='test'?button(a.paused?'Resume test':'Pause test','pause','small'):''}${button('Restore original','undo','small')}</div></div><div class="empty-wait"><h3>The next useful update</h3><p>We’ll surface your first exposure, a collection problem, or enough new evidence to review. There is no promised winner or deadline.</p><label class="consent"><input type="checkbox" id="notify-preference" ${state.notifications?'checked':''}>Also notify me by email when there is a useful update.</label><p class="fine">Demo preference only. No email address is collected and no email is sent.</p></div></aside></div></div>${footer(button('Back to my setup','go:dashboard',''),button('See what visitors did'+icon('arrow'),'go:followup'))}`;}
function collectionPanel(){if(state.collection==='unknown')return '';return `<div class="collection-panel" role="status"><h3>${state.collection==='consent'?'Waiting for visitor consent':state.collection==='blocked'?'No collection event received':'Connection checked; waiting for exposure'}</h3><p>${state.collection==='consent'?'Consent has not been granted in this scenario. Do not bypass it to complete onboarding. Test with an eligible consenting visitor.':state.collection==='blocked'?'Check whether tracking is blocked, the section is visible, and this is the production installation. Preview traffic is excluded.':'A connection alone does not prove collection. Leave the experience live, then return after a valid non-preview block view arrives.'}</p></div>`;}

function followup(){const a=state.active;const noData=state.scenario==='no-data'||!a?.exposed;const personal=a?.mode==='personalization';return `<div class="screen-body main-in"><div class="page-title"><div><h1>${noData?'Your next step is to verify delivery.':'Your next decision starts with evidence.'}</h1><p>${noData?'There is no exposure to interpret yet. Your saved idea is not lost.':'A useful return, triggered by activity rather than a calendar deadline.'}</p></div><span class="status purple">${noData?'No exposure recorded':'Illustrative early activity'}</span></div><div class="follow-layout"><div>${noData?`<div class="error-state"><h3>${a?'Published, waiting for a valid block view':'Draft prepared, not published'}</h3><p>${a?'Check the production connection, consent, audience match and visible section before changing the idea.':'Finish the optional launch setup when you are ready. A draft cannot receive visitor exposure.'}</p>${button(a?'Check visitor collection':'Return to my draft',a?'tracking-check':'go:preview')}${collectionPanel()}</div>`:`<div class="result-numbers"><div><b>312</b><span>Eligible block views</span></div><div><b>9</b><span>Link-click events</span></div></div><table class="result-table"><thead><tr><th>${personal?'Audience':'Version'}</th><th>Block views</th><th>Clicks</th></tr></thead><tbody><tr><td>${personal?'Campaign “migration”':'Original'}</td><td>158</td><td>4</td></tr><tr><td>${personal?'Other eligible visitors':'New version'}</td><td>154</td><td>5</td></tr></tbody></table><div class="notice">${personal?'Different audiences are not a controlled comparison. These counts do not establish uplift.':'No winner yet. A one-click difference does not justify a decision. Keep collecting evidence if this question still matters.'}</div><div class="verdict"><h3>A new observation to explore</h3><p>In this sample, your services page now receives more visits than the homepage. That changes our initial guess, not the result of your current test.</p>${button('Prepare a separate services draft','explore-services','primary small')}${button('Keep the current experience','keep-running','small')}</div>`}</div><aside class="return-note"><h3>${state.notifications?'Your optional email invitation':'Your next step, saved in Accelerate'}</h3><p>${noData?'Your first draft is ready. Collection is the next thing to check.':'There is new activity on your first experience. Review what was seen, what was clicked, and what remains uncertain.'}</p>${button(noData?'Open collection check':'Open this result',noData?'tracking-check':'return-focus','dark small')}<p class="fine">${state.notifications?'Example notification. Preference saved locally; nothing sent.':'Email is optional. The same result stays available in your setup hub.'}</p></aside></div></div>${footer(button('My setup','go:dashboard',''),`<label class="scenario">Reviewer scenario<select id="traffic-scenario"><option value="normal" ${!noData?'selected':''}>Example activity</option><option value="no-data" ${noData?'selected':''}>No eligible exposure</option><option value="consent" ${state.scenario==='consent'?'selected':''}>Consent withheld</option><option value="blocked" ${state.scenario==='blocked'?'selected':''}>Tracking blocked</option></select></label>`)}`;}

function dashboard(){const a=state.active;const items=[['Site connected',state.connected,'connect-wordpress'],['First draft prepared',state.prepared,'go:preview'],['Placement approved and published',!!a,'review-setup'],['Valid visitor exposure',!!a?.exposed,a?'go:live':'review-setup']];const done=items.filter(i=>i[1]).length;return `<div class="screen-body main-in"><div class="page-title"><div><h1>Your next step is waiting here.</h1><p>You can use Accelerate without finishing setup. Your draft, choices and progress are saved in this browser.</p></div><span class="status neutral">Optional setup · ${done} of 4</span></div><div class="dashboard-empty"><div class="resume-banner"><h3>${a?'Your first experience is '+(a.paused?'paused':'running'):'Your first draft is '+(state.prepared?'ready':'waiting to be prepared')}</h3><p>${a?'Your live experience is separate from any new draft you prepare.':'Come back to the result you already have; no need to answer the same questions again.'}</p><div class="button-row">${button(state.prepared?'Continue my draft':'Prepare my first idea',state.prepared?'go:preview':'go:connect')}${a?button('View live experience','go:live',''):''}</div></div>${state.setupHidden?`<div class="empty-wait"><h3>Setup checklist hidden</h3>${button('Show setup checklist','show-checklist','small')}</div>`:`<div class="setup-checklist"><h3>From a useful draft to real delivery</h3>${items.map(([label,done,action])=>`<button data-action="${action}" class="setup-item"><span>${icon(done?'check':'clock')}</span><strong>${label}</strong><span class="fine">${done?'Done':'Continue'}</span></button>`).join('')}<button class="text-button" data-action="hide-checklist">Hide this optional checklist</button></div>`}</div><details class="proposal-detail"><summary>Setup settings and re-entry</summary><p>Your saved answers stay with the draft. Reopening the introduction does not erase them.</p><div class="button-row">${button('Reopen introduction','go:connect','small')}${button('Review site understanding','go:understand','small')}${button('Review connection','connect-wordpress','small')}</div><label class="consent"><input type="checkbox" id="notify-preference" ${state.notifications?'checked':''}>Email me when there is useful new evidence (demo preference).</label></details>${state.connected?attribution():''}${receipt()}</div>${footer('<span class="fine">Nothing is published by leaving or skipping setup.</span>',button('Resume last step','resume',''))}`;}
function receipt(){return `<details class="proposal-detail"><summary>Prototype activity receipt · ${state.events.length} events</summary><p class="fine">Local simulation only. No URLs, content, prompts or visitor data in these events.</p><ol class="event-receipt">${state.events.slice(-14).map(e=>`<li><time>${esc(e.at)}</time> <strong>${esc(e.name)}</strong> <span>${esc(e.detail||'')}</span></li>`).join('')}</ol></details>`;}
const notes={connect:['One action earns a visible draft.','Assisted analysis is opt-in. Original-content editing remains available.','P1 / P3 / P5 / P10. First value is a useful draft, not connection completion.'],scan:['Make unavoidable waiting useful.','Show work progress, an available-content exit and optional attribution only after connection.','P4 / P6. AI prompt stays outside event telemetry.'],understand:['Correct the inference only when needed.','Optional business correction and three concrete directions visibly change the draft.','P3 / P8. No unrelated role or team-size questionnaire.'],recommend:['Let people override the starting point.','Three evidence-labelled pages; homepage recommendation is not a traffic ranking.','P1 / P8. Record selection without a raw URL.'],'website-connect':['Value before permission.','Explain scope, preserve the draft and model failed or pending authorisation.','P5 adapted / P9 / P12. No credential collection.'],preview:['The result is the tour.','Compare two invitations, try narrow view and inspect exact changes. Launch setup comes afterwards.','P1 / P2 / P10. Sample result, not WordPress runtime proof.'],launch:['Approve one concrete change.','Scope, exact content difference, registered measurement and blockers before approval.','P10 / P13. Approval is invalidated when content or scope changes.'],live:['Celebrate delivery milestones honestly.','Published and verified is distinct from valid visitor exposure. Restore and collection diagnosis remain available.','P2 / P7. Exposure is the proposed activation milestone, not yet proven retention-predictive.'],followup:['Return to new evidence.','No calendar-driven winner promise. Consent/no-data states explain what to check.','P2 / P12. In-app always, email optional and simulated.'],dashboard:['Skipping is a saved state.','Four optional milestones, hide/reopen checklist, settings and separate live/draft access.','P7 / P12. Receipt is local prototype instrumentation only.']};

function render(){
  document.body.dataset.entry=state.entry||'plugin';
  const focusId=document.activeElement?.id;
  const focusAction=document.activeElement?.dataset?.action;
  if(![...steps.map(s=>s[0]),'dashboard','website-connect'].includes(state.step))state.step='connect';
  if(!pages[state.page])state.page='home';if(!goals[state.goal])state.goal='Leads';
  const idx=steps.findIndex(s=>s[0]===state.step);
  $('#journey').innerHTML=steps.map(([id,label],i)=>`<button class="${id===state.step?'active':state.events.some(e=>e.name==='step_viewed'&&e.detail===id)?'done':''}" data-action="jump:${id}" ${id===state.step?'aria-current="step"':''}><span class="number">${i+1}</span>${label}</button>`).join('');
  $('#site-label').textContent=state.step==='connect'?'Your first improvement':state.url;
  $('#save-exit').hidden=state.step==='dashboard';
  $('#screen').innerHTML=({'connect':connect,'scan':scan,'understand':understand,'recommend':recommend,'website-connect':websiteConnect,'preview':preview,'launch':launch,'live':live,'followup':followup,'dashboard':dashboard}[state.step])();
  $('#design-notes').hidden=!state.notes;$('#notes-toggle').setAttribute('aria-expanded',String(state.notes));
  const n=notes[state.step];$('#design-notes').innerHTML=`<h2>Behind this moment</h2><div class="note-grid"><div><h3>Intent</h3><p>${n[0]}</p></div><div><h3>Behaviour</h3><p>${n[1]}</p></div><div><h3>Evidence & measurement</h3><p>${n[2]}</p></div></div><p class="fine">Design exploration only. Fictional business, example copy and simulated data. No public site is scanned, no email is sent, and no WordPress content changes. Journey navigation is for reviewers; it can seed clearly simulated live states.</p>${receipt()}`;
  if(focusId)document.getElementById(focusId)?.focus({preventScroll:true});
  else if(focusAction)[...document.querySelectorAll('[data-action]')].find(el=>el.dataset.action===focusAction)?.focus({preventScroll:true});
}
function startScan(){clearInterval(scanTimer);scanTimer=setInterval(()=>{if(state.step!=='scan'||state.scenario==='scan-error'){clearInterval(scanTimer);return;}state.scan=Math.min(4,state.scan+1);save();const formFocused=['ai-prompt','other-source','ai-tool'].includes(document.activeElement?.id);if(!formFocused)render();else if(state.scan===4){const next=$('#screen .footer > .btn');if(next){next.textContent='See my prepared idea';next.dataset.action='go:preview';}}if(state.scan===4){clearInterval(scanTimer);record('first_task_completed','assisted_draft');save();}},1100);}
document.addEventListener('submit',event=>{
 if(event.target.id==='headline-form'){event.preventDefault();saveHeadline();return;}
 if(event.target.id!=='connect-form')return;event.preventDefault();const value=$('#site-url').value.trim();
 try{const parsed=new URL(value.includes('://')?value:'https://'+value);if(!['http:','https:'].includes(parsed.protocol)||!parsed.hostname.includes('.')||parsed.username||parsed.password)throw new Error();state.url=parsed.hostname+(parsed.pathname==='/'?'':parsed.pathname.replace(/\/$/,''));}catch(_){$('#url-error').textContent='Enter a public website address, such as example.com.';$('#site-url').setAttribute('aria-invalid','true');$('#site-url').focus();return;}
 changed();state.assistance='assisted';state.scan=0;state.scenario='normal';record('first_task_started','assisted');go('scan');
});
function saveHeadline(){const value=$('#variant-edit').value.trim();if(!value)return toast('Add a headline for this draft.');if(state.mode==='personalization')state.personalizedVariant=value;else state.variant=value;changed();state.edit=false;record('proposal_edited','headline');save();render();}
function skip(){record('step_skipped',state.step);state.resume=state.step;go('dashboard');toast('Draft saved. Continue setup whenever you need it.');}
function prepareManual(){state.assistance='manual';state.variant=currentPage().original;state.personalizedVariant=currentPage().original;changed();record('first_task_started','manual');go('preview');}
function snapshot(){return {page:state.page,variant:headline(),mode:state.mode,paused:false,exposed:false};}
function setup(){state.reviewed=true;record('proposal_reviewed','content_and_scope');go(!state.connected?'website-connect':'launch');}
document.addEventListener('input',event=>{const fields={'ai-prompt':'aiPrompt','other-source':'otherSource'};if(fields[event.target.id]){state[fields[event.target.id]]=event.target.value;save();}});
document.addEventListener('change',event=>{
 if(event.target.id==='launch-consent'){state.approved=event.target.checked;record(state.approved?'approval_granted':'approval_withdrawn','placement');save();$('[data-action="launch"]').disabled=!state.approved||launchBlocked();}
 if(event.target.id==='scan-scenario'){state.scenario=event.target.value;state.scan=0;if(state.scenario==='scan-error')record('first_task_failed','analysis_unavailable');go('scan');}
 if(event.target.id==='readiness-scenario'){state.readiness=event.target.value;changed();if(state.readiness==='permission')record('permission_denied','role');save();render();}
 if(event.target.id==='connection-scenario'){state.connectionState=event.target.value;record('connection_state',state.connectionState);save();render();}
 if(event.target.id==='traffic-scenario'){state.scenario=event.target.value;if(['consent','blocked'].includes(state.scenario)){state.collection=state.scenario;state.scenario='no-data';}if(state.active)state.active.exposed=state.scenario==='normal';save();render();}
 if(event.target.id==='ai-tool'){state.aiTool=event.target.value;record('attribution_followup','tool_selected');save();}
 if(event.target.id==='notify-preference'){state.notifications=event.target.checked;record('notification_preference',state.notifications?'enabled':'disabled');save();toast('Preference saved in this demo. No email will be sent.');}
});
document.addEventListener('click',event=>{
 const target=event.target.closest('[data-action]');if(!target)return;const [name,value]=target.dataset.action.split(':');
 if(name==='go')return go(value);
 if(name==='jump'){if(value!=='connect'&&value!=='scan')state.scan=4;if(value==='live'||value==='followup'){state.active=snapshot();state.active.exposed=value==='followup';record('review_fixture_loaded',value);}return go(value);}
 if(name==='skip')return skip();
 if(name==='manual')return prepareManual();
 if(name==='assist'){state.assistance='assisted';state.variant=currentPage().headline;state.personalizedVariant=initial.personalizedVariant;changed();record('first_task_started','assisted');return go('preview');}
 if(name==='entry'){state.entry=value;state.connected=value==='plugin';}
 if(name==='discovery'){state.discovery=value;record('attribution_answered',value);}
 if(name==='goal'){state.goal=value;state.assistance='assisted';state.variant=value==='Clarity'?'A clear path to your next website.':value==='Confidence'?'A new foundation. A team beside you.':currentPage().headline;changed();}
 if(name==='page'){state.page=value;state.variant=currentPage().headline;changed();}
 if(name==='idea'){state.idea=value;state.goal=value==='cta'?'Clarity':value==='proof'?'Confidence':'Leads';state.variant=value==='proof'?'A new foundation. A team beside you.':value==='cta'?'A clear path to your next website.':currentPage().headline;changed();}
 if(name==='device'){state.device=value;record('preview_checked',value);}
 if(name==='mode'){state.mode=value;changed();toast('Review the updated experience before approving launch.');return go('preview');}
 if(name==='review-setup')return setup();
 if(name==='edit-brief'||name==='edit-variant')state.edit=true;
 if(name==='cancel-edit')state.edit=false;
 if(name==='save-brief'){const v=$('#brief-edit').value.trim();if(!v)return toast('Add a short description or keep the current one.');state.brief=v;state.edit=false;changed();record('brief_corrected','business_description');}
 if(name==='retry'){state.scenario='normal';state.scan=0;return go('scan');}
 if(name==='local-content'){state.scenario='local';state.scan=4;record('first_task_completed','available_content');return go('preview');}
 if(name==='connect-wordpress')return go('website-connect');
 if(name==='finish-wordpress'){state.connected=true;state.connectedUrl=state.url;state.connectionState='ready';state.readiness='ready';changed();record('permission_granted','site_scoped_connection');return go('launch');}
 if(name==='resolve-readiness'){
  if(state.readiness==='permission'){state.connectionState='pending';return go('website-connect');}
  if(state.readiness==='unmapped'){state.page='home';state.variant=pages.home.headline;}
  if(state.readiness==='stale'){state.sourcePage=state.page;state.sourceHeading='Your website, ready for what comes next.';record('source_refreshed','review_required');}
  const prev=state.readiness;state.readiness='ready';changed();record('preparation_recovered',prev);return go('preview');
 }
 if(name==='launch'){
  if(!state.approved||launchBlocked())return;record('publish_attempted','approved_placement');
  if(state.readiness==='publish-failure'){state.readiness='failed';changed();record('publish_failed','verification');record('original_restored','simulated_transaction');return go('launch');}
  state.active=snapshot();state.launched=true;record('publish_verified','one_placement');return go('live');
 }
 if(name==='exposure'&&state.active&&!state.active.paused){state.active.exposed=true;record('valid_exposure','simulated_non_preview');toast('Simulated valid exposure recorded.');}
 if(name==='pause'&&state.active?.mode==='test'){state.active.paused=!state.active.paused;record(state.active.paused?'test_paused':'test_resumed','original_available');}
 if(name==='undo'&&state.active){state.active=null;state.launched=false;changed();record('original_restored','draft_retained');toast('Original restored in this example. Draft kept.');return go('preview');}
 if(name==='explore-services'){state.page='services';state.variant=pages.services.headline;changed();record('next_draft_prepared','services');return go('preview');}
 if(name==='keep-running')return go('live');
 if(name==='tracking-check'){if(state.collection==='unknown')state.collection='waiting';record('collection_checked',state.collection);save();render();$('.collection-panel')?.scrollIntoView({block:'nearest'});return;}
 if(name==='return-focus'){const el=$('.result-numbers')||$('.error-state');el?.scrollIntoView({block:'center'});el?.setAttribute('tabindex','-1');el?.focus({preventScroll:true});return;}
 if(name==='hide-checklist')state.setupHidden=true;
 if(name==='show-checklist')state.setupHidden=false;
 if(name==='resume'){record('onboarding_resumed',state.resume);return go(state.resume==='dashboard'?'preview':state.resume);}
 save();render();if(state.edit)($('#brief-edit')||$('#variant-edit'))?.focus();
});
$('#save-exit').addEventListener('click',skip);
$('#restart').addEventListener('click',()=>{state={...initial,events:[],notes:state.notes};record('onboarding_started','reviewer_restart');go('connect');toast('Only this prototype’s progress was reset.');});
$('#notes-toggle').addEventListener('click',()=>{state.notes=!state.notes;save();render();if(state.notes)$('#design-notes').scrollIntoView({behavior:'smooth',block:'nearest'});});
window.addEventListener('hashchange',()=>{const id=location.hash.slice(1);if([...steps.map(s=>s[0]),'dashboard','website-connect'].includes(id))go(id);});
if(!state.events.length)record('onboarding_started',state.entry);
const first=location.hash.slice(1)||state.step;go(first);
